INSERT INTO boe_inject.unit_version_stage (id,unit_id,body,valid_from,evidence_instrument,evidence_url,evidence_quote) VALUES
('boe26-21f15d1a9065441e19f4a0b1','cmpz5wixw01kvcwg2n7s3ku4t','يكون منح جواز السفر وتصريح السفر للخاضعين للحضانة والقصّر المتوفى وليّهم، وفقاً لما تحدده اللائحة التنفيذية','2019-07-30','مرسوم ملكي رقم م/134 وتاريخ 27/11/1440هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/e29f08fa-d53e-4944-b22b-a9a700f17fd9/1','عُدلت هذه المادة بموجب المرسوم الملكي رقم (م / 134) وتاريخ 27 / 11 / 1440هـ ، لتكون بالنص الآتي: "يكون منح جواز السفر وتصريح السفر للخاضعين للحضانة والقصّر المتوفى وليّهم، وفقاً لما تحدده اللائحة التنفيذية".'),
('boe26-b443994d0616d9e1a3dbffc8','cmpzcv6wn0aapvtrkeyfvjwuy','دون إخلال باختصاصات ومسؤوليات الجهات الأخرى ذات العلاقة، تتولى الوزارة - في سبيل تنفيذ أحكام هذا النظام- جميع الصلاحيات والمهمات المتعلقة بتنظيم أوجه النشاط الخاضعة لهذا النظام، ولها على وجه الخصوص ما يأتي:

1- إعداد خطة طويلة المدى للإمداد بكميات الغاز الجاف وغاز البترول السائل اللازمة للاستهلاك السكني والتجاري، واعتمادها وتحديثها ومتابعة تنفيذها، وذلك بما يحقق الاستخدام الأمثل.

2- إصدار الرخص اللازمة لمزاولة أوجه النشاط، وتحصيل المقابل المالي للرخص.

3- تشجيع التنافس، ومراقبة ظروف السوق ذات الصلة والمستجدات، وتقويمها، واتخاذ ما يلزم حيالها، بما يحقق التغطية الجغرافية المناسبة.

4- ضمان توفر إمدادات الغاز الجاف وغاز البترول السائل للمستهلك النهائي، ومتابعة التزام المرخص لهم بتشغيل شبكات توزيع الغاز الجاف وشبكات الغاز المستقلة وتجار التجزئة بتوفير منتج الغاز الجاف أو غاز البترول السائل للمستهلكين.

5- اعتماد التعريفة بقرار من الوزير، مع مراعاة الآتي

أ- سعر الغاز الجاف، وسعر غاز البترول السائل، المعتمدان.

ب- تمكين المرخص له من التشغيل بكفاية لاستعادة التكاليف كاملة وتحقيق هامش ربح عادل. ويؤخذ في الاعتبار عند تحديد ذلك أفضل الممارسات العالمية واستيفاء الاشتراطات الواردة في الأنظمة واللوائح ذات العلاقة.

ج- تقديم حوافز لاستمرار تحسين الكفاية الفنية والاقتصادية وجودة الخدمة.

د- مراعاة الترتيبات التعاقدية القائمة وقت سريان هذا النظام.','2022-06-08','مرسوم ملكي رقم م/112 وتاريخ 1443/11/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/e4436403-31ee-439c-bac4-a9a700f2a17d/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/112) وتاريخ 1443/11/9هـ، لتكون بالنص الآتي: "دون إخلال باختصاصات ومسؤوليات الجهات الأخرى ذات العلاقة، تتولى الوزارة - في سبيل تنفيذ أحكام هذا النظام- جميع الصلاحيات والمهمات المتعلقة بتنظيم أوجه النشاط الخاضعة لهذا النظام، ولها على وجه الخصوص ما يأتي:

1- إعداد خطة طويلة المدى للإمداد بكميات الغاز الجاف وغاز البترول السائل اللازمة للاستهلاك السكني والتجاري، واعتمادها وتحديثها ومتابعة تنفيذها، وذلك بما يحقق الاستخدام الأمثل.

2- إصدار الرخص اللا'),
('boe26-af0f6b3761cf8682cd0acc8f','cmpzcv6wn0aaqvtrk24c7wzgu','أوجه النشاط الخاضعة لهذا النظام هي:

1- إنشاء شبكة توزيع الغاز الجاف أو شبكة الغاز المستقلة، أو تطويرها أو تشغيلها أو صيانتها، وربط المنشآت السكنية والتجارية بها، وتزويد المستهلك بالغاز الجاف أو غاز البترول السائل أو الغاز الطبيعي البديل.

2- نقل غاز البترول السائل من مصادره إلى مرافق غاز البترول السائل أو شبكة توزيع الغاز المستقلة.

3- إنشاء مرافق تعبئة وتخزين غاز البترول السائل، أو تطويرها أو تشغيلها أو صيانتها.

4- توزيع غاز البترول السائل بالجملة.

5- بيع أسطوانات غاز البترول السائل بالتجزئة في الأماكن المعدة لهذا الغرض.','2022-06-08','مرسوم ملكي رقم م/112 وتاريخ 1443/11/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/e4436403-31ee-439c-bac4-a9a700f2a17d/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/112) وتاريخ 1443/11/9هـ، لتكون بالنص الآتي:

"أوجه النشاط الخاضعة لهذا النظام هي:

1- إنشاء شبكة توزيع الغاز الجاف أو شبكة الغاز المستقلة، أو تطويرها أو تشغيلها أو صيانتها، وربط المنشآت السكنية والتجارية بها، وتزويد المستهلك بالغاز الجاف أو غاز البترول السائل أو الغاز الطبيعي البديل.

2- نقل غاز البترول السائل من مصادره إلى مرافق غاز البترول السائل أو شبكة توزيع الغاز المستقلة.

3- إنشاء مرافق تعبئة وتخزين غاز البترول السائل، أو تطويرها أو تشغي'),
('boe26-850388769499adef4cc2d95a','cmpzcuy3x07u6vtrkdtpllt25','يشترط فيمن يشغل درجة قاضي (ب) أن يكون قد قضى سنة على الأقل في درجة قاضي (ج)، أو اشتغل بأعمال قضائية نظيرة لمدة أربع سنوات على الأقل، أو قام بتدريس الفقه أو أصوله في إحدى الكليات بالمملكة لمدة أربع سنوات على الأقل، أو يكون حاصلاً على شهادة الماجستير من المعهد العالي للقضاء، أو من إحدى كليات الشريعة في المملكة في تخصص الفقه أو أصوله، أو يكون حاصلاً على دبلوم من معهد الإدارة في تخصص القانون لا تقل مدة دراسته المعتمدة عن سنتين من الحاملين لشهادة إحدى كليات الشريعة في المملكة بتقدير عام لا يقل عن (جيد) وبتقدير لا يقل عن (جيد جداً) في الفقه وأصوله','2020-06-11','مرسوم ملكي رقم م/141 وتاريخ 1441/10/19هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ea1765a3-dec3-41a0-a32f-a9a700f26d58/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/141) وتاريخ 1441/10/19هـ، لتكون بالنص الآتي: 

"يشترط فيمن يشغل درجة قاضي (ب) أن يكون قد قضى سنة على الأقل في درجة قاضي (ج)، أو اشتغل بأعمال قضائية نظيرة لمدة أربع سنوات على الأقل، أو قام بتدريس الفقه أو أصوله في إحدى الكليات بالمملكة لمدة أربع سنوات على الأقل، أو يكون حاصلاً على شهادة الماجستير من المعهد العالي للقضاء، أو من إحدى كليات الشريعة في المملكة في تخصص الفقه أو أصوله، أو يكون حاصلاً على دبلوم من معهد الإدارة في تخصص القانون لا تقل مد'),
('boe26-d21ce6bc8e82154214873b9b','cmpz5ub5g00u3cwg2nmgrlbgr','يلتزم كل مسؤول في المطبوعة بالنقد الموضوعي والبناء الهادف إلى المصلحة العامة، والمستند إلى وقائع وشواهد صحيحة. ويحظر أن يُنشر بأي وسيلة كانت أي مما يأتي :

1 - ما يخالف أحكام الشريعة الإسلامية أو الأنظمة النافذة.

2 - ما يدعو إلى الإخلال بأمن البلاد أو نظامها العام، أو ما يخدم مصالح أجنبية تتعارض مع المصلحة الوطنية.

3 - التعرض أو المساس بالسمعة أو الكرامة أو التجريح أو الإساءة الشخصية إلى مفتي عام المملكة أو أعضاء هيئة كبار العلماء أو رجال الدولة أو أي من موظفيها أو أي شخص من ذوي الصفة الطبيعية أو الاعتبارية الخاصة.

4 - إثارة النعرات وبث الفرقة بين المواطنين.

5 - تشجيع الإجرام أو الحث عليه.

6 - ما يضر بالشأن العام في البلاد.

7 - وقائع التحقيقات أو المحاكمات، دون الحصول على إذن من الجهة المخولة نظامًا','2012-03-04','مرسوم ملكي رقم م/20 وتاريخ 11/4/1433هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ecaaec43-8ff9-46b8-b269-a9a700f16e66/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م / 20 ) وتاريخ 11 / 4 / 1433 هـ ، لتصبح كما يلى :

"يلتزم كل مسؤول في المطبوعة بالنقد الموضوعي والبناء الهادف إلى المصلحة العامة، والمستند إلى وقائع وشواهد صحيحة. ويحظر أن يُنشر بأي وسيلة كانت أي مما يأتي :

1 - ما يخالف أحكام الشريعة الإسلامية أو الأنظمة النافذة.

2 - ما يدعو إلى الإخلال بأمن البلاد أو نظامها العام، أو ما يخدم مصالح أجنبية تتعارض مع المصلحة الوطنية.

3 - التعرض أو المساس بالسمعة أو الكرامة أو التجريح أو الإساءة الشخصية إلى مفتي عا'),
('boe26-abe0807748f1d45f1a8b0d74','cmpz5ufh100vlcwg21xxr9cxb','للوزارة - عند الاقتضاء - سحب أي مطبوعة دون تعويض، إذا تضمنت أيًا من الأمور المحظور نشرها، المنصوص عليها في المادة (التاسعة) من هذا النظام','2012-03-04','مرسوم ملكي رقم م/20 وتاريخ 11/4/1433هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ecaaec43-8ff9-46b8-b269-a9a700f16e66/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/20 ) وتاريخ 11 / 4 / 1433 هـ، لتصبح كما يلى :

" للوزارة - عند الاقتضاء - سحب أي مطبوعة دون تعويض، إذا تضمنت أيًا من الأمور المحظور نشرها، المنصوص عليها في المادة (التاسعة) من هذا النظام".'),
('boe26-f20911428c8d6d01dbde822a','cmpz5ufms00vncwg24rmeb82u','1  - 	تشكل لجنة ابتدائية - أو أكثر - برئاسة من تتوافر فيه خبرة في الأعمال القضائية، وعضوية مستشار نظامي وأحد المختصين في الإعلام، للنظر في مخالفات أحكام هذا النظام وتطبيق العقوبات الواردة فيه.

2   -  لا تنظر اللجنة إلا في الشكاوي التي يرفعها أي شخص ممن له صفة ومصلحة مباشرة، أو ما يحال إليها من الوزير.

3   -  تصدر قرارات اللجنة الابتدائية بالإجماع أو بالأغلبية بعد دعوة المخالف أو من يمثله، وسماع أقواله، ويجوز لها دعوة من ترى الاستماع إلى أقواله.','2012-03-04','مرسوم ملكي رقم م/20 وتاريخ 11/4/1433هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ecaaec43-8ff9-46b8-b269-a9a700f16e66/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/20 ) وتاريخ 11 / 4 / 1433 هـ، لتصبح كما يلى :

" 1  - 	تشكل لجنة ابتدائية - أو أكثر - برئاسة من تتوافر فيه خبرة في الأعمال القضائية، وعضوية مستشار نظامي وأحد المختصين في الإعلام، للنظر في مخالفات أحكام هذا النظام وتطبيق العقوبات الواردة فيه.

2   -  لا تنظر اللجنة إلا في الشكاوي التي يرفعها أي شخص ممن له صفة ومصلحة مباشرة، أو ما يحال إليها من الوزير.

3   -  تصدر قرارات اللجنة الابتدائية بالإجماع أو بالأغلبية بعد دعوة المخالف أو من يمثله، وسماع أقو'),
('boe26-086b36b33364c53971e16038','cmpz5ug4100vtcwg2q1lleolf','1 -  تشكل لجنة استئنافية برئاسة من تتوافر فيه خبرة الأعمال القضائية وعضوية مستشار نظامي وأحد المختصين في الإعلام لا تقل الخبرة العملية لأي مهنهم عن خمس وعشرين سنة؛ للنظر في التظلمات المقدمة من ذوي الشأن على قرارات اللجنة الابتدائية المشار إليها في المادة (السابعة والثلاثين) من هذا النظام، وتصدر قراراتها بالإجماع أو بالأغلبية، وتكون نهائية غير قابلة للطعن أمام أي جهة أخرى.
2 -  يصدر الوزير القواعد المنظمة لعمل اللجنتين الابتدائية والاستئنافية وبيان اختصاصاتهما وفق ما هو وارد في هذا النظام.
3 -  يصدر أمر ملكي بتأليف اللجنتين الابتدائية والاستئنافية وتسمية رئيسيهما وأعضائهما، وتحدد في الأمر مكافآتهم. وتكون مدة العضوية في اللجنتين ثلاث سنوات قابلة للتجديد','2012-03-04','مرسوم ملكي رقم م/20 وتاريخ 11/4/1433هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ecaaec43-8ff9-46b8-b269-a9a700f16e66/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/20 ) وتاريخ 11 / 4 / 1433هـ، لتصبح كما يلى :

"1 -  تشكل لجنة استئنافية برئاسة من تتوافر فيه خبرة الأعمال القضائية وعضوية مستشار نظامي وأحد المختصين في الإعلام لا تقل الخبرة العملية لأي مهنهم عن خمس وعشرين سنة؛ للنظر في التظلمات المقدمة من ذوي الشأن على قرارات اللجنة الابتدائية المشار إليها في المادة (السابعة والثلاثين) من هذا النظام، وتصدر قراراتها بالإجماع أو بالأغلبية، وتكون نهائية غير قابلة للطعن أمام أي جهة أخرى.
2 -  يصدر الوزير القواعد المنظ'),
('boe26-0ddeb9361ab8894baa7f7599','cmpz5xy3z022hcwg29amf80dy','لا يجوز نزع أي آلة أو إشارة مركبة لأغراض الدفاع المدني أو تعطيلها إلا بعد التنسيق مع الدفاع المدني، ويلزم المخالف بتكاليف إعادة أصل الشيء المنزوع أو المعطل إلى حالته السابقة، ويعاقب بغرامة لا تتجاوز خمسين ألف ريال" .','2003-11-26','مرسوم ملكي رقم م/66 وتاريخ 2/10/1424هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/f09eda85-7150-4803-b87a-a9a700f189f3/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/66) وتاريخ 2 / 10 / 1424 هـ ، لتصبح بالنص التالى :

" لا يجوز نزع أي آلة أو إشارة مركبة لأغراض الدفاع المدني أو تعطيلها إلا بعد التنسيق مع الدفاع المدني، ويلزم المخالف بتكاليف إعادة أصل الشيء المنزوع أو المعطل إلى حالته السابقة، ويعاقب بغرامة لا تتجاوز خمسين ألف ريال" .'),
('boe26-46738983b0969270bd11830a','cmpz5xy9k022jcwg26a9mzde3','مع مراعاة ما تقضي به الأنظمة، يصدر   وزير الداخلية     رئيس مجلس الدفاع المدني في حالات الطوارئ والكوارث، قرارات بتنفيذ خطة الدفاع المدني، ويعين في قراراته العقوبات التي تطبق على من يخالف الخطة، على ألا تتجاوز عقوبة السجن مدة سنة وغرامة مالية لا تتجاوز خمسين ألف ريال أو إحدى هاتين العقوبتين','2003-11-26','مرسوم ملكي رقم م/66 وتاريخ 2/10/1424هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/f09eda85-7150-4803-b87a-a9a700f189f3/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/66) وتاريخ 2 / 10 / 1424 هـ،   لتصبح بالنص التالى :

"مع مراعاة ما تقضي به الأنظمة، يصدر   وزير الداخلية     رئيس مجلس الدفاع المدني في حالات الطوارئ والكوارث، قرارات بتنفيذ خطة الدفاع المدني، ويعين في قراراته العقوبات التي تطبق على من يخالف الخطة، على ألا تتجاوز عقوبة السجن مدة سنة وغرامة مالية لا تتجاوز خمسين ألف ريال أو إحدى هاتين العقوبتين".'),
('boe26-a6ef579afb01600db1a8533e','cmpz5xyf4022lcwg2chghzrpw','أ - مع مراعاة المواد (السابعة والعشرين) و (الثامنة والعشرين) و (التاسعة والعشرين) ، يعاقب المخالف لأي حكم من أحكام هذا النظام أو لوائحه أو القرارات الصادرة بناء عليه، بالسجن مدة لا تزيد على ستة أشهر، أو بغرامة لا تزيد على ثلاثين ألف ريال أو بهما معا.
ب - يشكل   وزير الداخلية  رئيس مجلس الدفاع المدني لجانا، تتكون كل لجنة من ثلاثة أعضاء على الأقل، يكون أحدهم من ذوي التأهيل الشرعي أو النظامي، وذلك للنظر في مخالفات هذا النظام، وإيقاع عقوبة الغرامة المنصوص عليها فيه. وإذا رأت اللجنة أن المخالفة تستوجب عقوبة السجن فتحال إلى ديوان المظالم.','2003-11-26','مرسوم ملكي رقم م/66 وتاريخ 2/10/1424هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/f09eda85-7150-4803-b87a-a9a700f189f3/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/66) وتاريخ 2 / 10 / 1424 هـ،  لتصبح بالنص التالى :

" أ - مع مراعاة المواد (السابعة والعشرين) و (الثامنة والعشرين) و (التاسعة والعشرين) ، يعاقب المخالف لأي حكم من أحكام هذا النظام أو لوائحه أو القرارات الصادرة بناء عليه، بالسجن مدة لا تزيد على ستة أشهر، أو بغرامة لا تزيد على ثلاثين ألف ريال أو بهما معا.
ب - يشكل   وزير الداخلية  رئيس مجلس الدفاع المدني لجانا، تتكون كل لجنة من ثلاثة أعضاء على الأقل، يكون أحدهم من ذوي التأهيل الشرعي أو النظامي، وذلك'),
('boe26-da0a45ebbd669e8fe19a2089','cmpz5xykp022ncwg2p23m2q05','يجوز التظلم من قرار العقوبة أمام   ديوان المظالم خلال ستين يوما من تاريخ إبلاغ القرار.','2003-11-26','مرسوم ملكي رقم م/66 وتاريخ 2/10/1424هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/f09eda85-7150-4803-b87a-a9a700f189f3/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/66) وتاريخ 2 / 10 / 1424 هـ ،    لتصبح بالنص التالى :

"يجوز التظلم من قرار العقوبة أمام   ديوان المظالم خلال ستين يوما من تاريخ إبلاغ القرار."'),
('boe26-e3370a95c58af1f0a358e40f','cmpwia9d501ptnxffcwsf7w94','إذا لم يحضر المدعي أي جلسة من جلسات الدعوى ولم يتقدم بعذر تقبله المحكمة، فلها أن تقرر شطبها. فإذا انقضت (ستون) يوماً ولم يطلب المدعي السير فيها بعد شطبها، أو لم يحضر بعد السير فيها، عٌدَّت كأن لم تكن','2019-11-27','مرسوم ملكي رقم م/38 وتاريخ 30/3/1441هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/f0eaae46-9f84-40ee-815e-a9a700f268b3/1','عٌدلت هذه المادة بموجب المرسوم الملكي رقم (م / 38) وتاريخ 30 / 3 / 1441هـ، لتكون بالنص الآتي:

"إذا لم يحضر المدعي أي جلسة من جلسات الدعوى ولم يتقدم بعذر تقبله المحكمة، فلها أن تقرر شطبها. فإذا انقضت (ستون) يوماً ولم يطلب المدعي السير فيها بعد شطبها، أو لم يحضر بعد السير فيها، عٌدَّت كأن لم تكن".'),
('boe26-d7b01b75799da248f0683b5f','cmpwia9p201pvnxff7osr2iog','إذا لم يحضر المدعي جلسات الدعوى - وفقاً لما ورد في المادة (الخامسة والخمسين) من هذا النظام - فللمدعى عليه أن يطلب من المحكمة الحكم في موضوعها، وعلى المحكمة أن تحكم إذا كانت صالحة للحكم فيها، يُعدّ حكمها في حق المدعي حضوريا','2019-11-27','مرسوم ملكي رقم م/38 وتاريخ 30/3/1441هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/f0eaae46-9f84-40ee-815e-a9a700f268b3/1','عُدلت هذه المادة بموجب المرسوم الملكي رقم (م / 38) وتاريخ 30 / 3 / 1441هـ، لتكون بالنص الآتي:

"إذا لم يحضر المدعي جلسات الدعوى - وفقاً لما ورد في المادة (الخامسة والخمسين) من هذا النظام - فللمدعى عليه أن يطلب من المحكمة الحكم في موضوعها، وعلى المحكمة أن تحكم إذا كانت صالحة للحكم فيها، يُعدّ حكمها في حق المدعي حضوريا".'),
('boe26-dc55ecd664959c60a7eb5a7f','cmpwi9t8e01n5nxffoqi8fsxh','لايجوز للمحضرين ولا للكتبة وغيرهم من أعوان القضاء أن يباشروا عملاً يدخل في حدود وظائفهم في الدعاوى الخاصة بهم أو بأزواجهم أو بأقاربهم أو بأصهارهم حتى الدرجة الرابعة، وكذا الإنهاءات إذا اشتملت على خصومة، وإلا كان هذا العمل باطلاً','2021-06-24','مرسوم ملكي رقم م/101 وتاريخ 1442/11/14هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/f0eaae46-9f84-40ee-815e-a9a700f268b3/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/101) وتاريخ 1442/11/14هـ، لتكون بالنص الآتي: "لايجوز للمحضرين ولا للكتبة وغيرهم من أعوان القضاء أن يباشروا عملاً يدخل في حدود وظائفهم في الدعاوى الخاصة بهم أو بأزواجهم أو بأقاربهم أو بأصهارهم حتى الدرجة الرابعة، وكذا الإنهاءات إذا اشتملت على خصومة، وإلا كان هذا العمل باطلاً".'),
('boe26-9f77aa0446efbff1268e566f','cmpwiacnm01qdnxffcksouoq5','1- تكون إجراءات نظر الدعوى والمرافعة فيها كتابة. وللمحكمة - من تلقاء نفسها أو بناءً على طلب أحد الخصوم - أن تسمع ما لدى الأطراف مشافهة. وتثبت المحكمة ذلك في محضر الجلسة.

2- على المحكمة أن تعطي الخصوم المهل المناسبة، للاطلاع على المستندات، كلما اقتضت الحال ذلك','2021-04-22','مرسوم ملكي رقم م/78 وتاريخ 1442/9/10هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/f0eaae46-9f84-40ee-815e-a9a700f268b3/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/78) وتاريخ 1442/9/10هـ، لتصبح بالنص الآتي:

" 1- تكون إجراءات نظر الدعوى والمرافعة فيها كتابة. وللمحكمة - من تلقاء نفسها أو بناءً على طلب أحد الخصوم - أن تسمع ما لدى الأطراف مشافهة. وتثبت المحكمة ذلك في محضر الجلسة.

2- على المحكمة أن تعطي الخصوم المهل المناسبة، للاطلاع على المستندات، كلما اقتضت الحال ذلك ".'),
('boe26-de062bab9f3deaac60af85cb','own26-6517279dd6395fdf6e89912f','تتألف الموارد المالية للهيئة من المصادر الآتية:

أ- ما يخصص للهيئة من المقابل المالي الذي تتقاضاه الدولة من التراخيص التي تصدرها الهيئة.

ب- المقابل المالي الذي تتقاضاه الهيئة من الأعمال والخدمات التي تقدمها وفقاً للتنظيم.

ج- حصيلة الغرامات المفروضة بموجب نظام الاتصالات وتقنية المعلومات.

د- المقابل المالي الذي تتقاضاه الهيئة لقاء تخصيص وإدارة موارد الترقيم، وموارد الطيف الترددي، وأسماء النطاقات السعودية والمعرفات التقنية.

هـ- ما قد يقدم إليها من إعانات أو منح من الدولة.

و- ما تحصل عليه نتيجة الانتفاع بمرافقها، وعائدات استثمار أموالها وأصولها، ومردودات بيعها، وفق الإجراءات النظامية.

ز- ما يقبله المجلس من منح وهبات وإعانات وتبرعات ووصايا وأوقاف، وفقاً للإجراءات النظامية.

ح- أي مورد آخر يقره المجلس بما لا يخالف الأنظمة والتعليمات','2024-12-24','قرار مجلس الوزراء رقم 430 وتاريخ 1446/6/23هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/f327464b-2f5a-475d-aa94-a9a700f2e817/1','- صدر قرار مجلس الوزراء رقم (430) وتاريخ 1446/6/23هـ، وذلك بتعديل هذه المادة لتكون بالنص  الآتي:

"تتألف الموارد المالية للهيئة من المصادر الآتية:

أ- ما يخصص للهيئة من المقابل المالي الذي تتقاضاه الدولة من التراخيص التي تصدرها الهيئة.

ب- المقابل المالي الذي تتقاضاه الهيئة من الأعمال والخدمات التي تقدمها وفقاً للتنظيم.

ج- حصيلة الغرامات المفروضة بموجب نظام الاتصالات وتقنية المعلومات.

د- المقابل المالي الذي تتقاضاه الهيئة لقاء تخصيص وإدارة موارد الترقيم، وموارد الطيف الترددي، وأسماء النطاقات ا'),
('boe26-a903628e8ec6f2a9048f7777','cmpz6l94j0a0ncwg2jt5e8pps','تقوم وزارة الحج والعمرة بتنفيذ قرارات اللجنة المنصوص عليها في المادة (التاسعة عشرة) من هذا النظام حال مصادقة وزير الحج والعمرة عليها، ويجوز لمن صدر بحقه قرار التظلم منه أمام المحكمة الإدارية المختصة','2024-01-07','مرسوم ملكي رقم م/109 وتاريخ 1445/6/25هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/f55f0003-8b87-4ff0-8f0f-a9a700f20578/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/109) وتاريخ 1445/6/25هـ، لتصبح بالنص الآتي: "تقوم وزارة الحج والعمرة بتنفيذ قرارات اللجنة المنصوص عليها في المادة (التاسعة عشرة) من هذا النظام حال مصادقة وزير الحج والعمرة عليها، ويجوز لمن صدر بحقه قرار التظلم منه أمام المحكمة الإدارية المختصة".'),
('boe26-9fdaf22dbae9ec7b88070ac8','cmpz6chaf06whcwg2hiyuhlls','يكون للصندوق مجلس إدارة برئاسة نائب رئيس مجلس الوزراء، وعضوية المحافظ، وأعضاء لا يقل عددهم عن سبعة، يصدر بتسميتهم أمر من رئيس مجلس الوزراء، وتكون مدة عضويتهم (ثلاث) سنوات قابلة للتجديد مرة واحدة.

ولرئيس المجلس إنابة من يراه من الأعضاء لرئاسة المجلس في حال غيابه','2019-05-07','قرار مجلس الوزراء رقم 505 وتاريخ 2/9/1440هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/fd05e9ef-bf19-4766-9121-a9ec01152301/1','•المادة الخامسة

-عُدلت هذه المادة بموجب قرار مجلس الوزراء رقم (505) وتاريخ 2 /9 / 1440هـ، لتصبح بالنص الآتي: "يكون للصندوق مجلس إدارة برئاسة نائب رئيس مجلس الوزراء، وعضوية المحافظ، وأعضاء لا يقل عددهم عن سبعة، يصدر بتسميتهم أمر من رئيس مجلس الوزراء، وتكون مدة عضويتهم (ثلاث) سنوات قابلة للتجديد مرة واحدة.

ولرئيس المجلس إنابة من يراه من الأعضاء لرئاسة المجلس في حال غيابه".'),
('boe26-8c823f3bf89f4f7026de9198','cmpz6cia406wtcwg22to4edd4','يخضع منسوبو الصندوق لنظام العمل ونظام التأمينات الأجتماعية','2019-05-07','قرار مجلس الوزراء رقم 505 وتاريخ 2/9/1440هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/fd05e9ef-bf19-4766-9121-a9ec01152301/1','-عُدلت هذه المادة بموجب قرار مجلس الوزراء رقم (505) وتاريخ 2 /9 / 1440هـ، لتكون بالنص الآتي: "يخضع منسوبو الصندوق لنظام العمل ونظام التأمينات الأجتماعية".'),
('boe26-c3a120fcd05ecfc13c2f5528','cmpz6cia406wtcwg22to4edd4','يخضع منسوبو الصندوق -عدا المحافظ- لنظام العمل ونظام التأمينات الاجتماعية','2025-10-14','قرار مجلس الوزراء رقم 284 وتاريخ 1447/4/22هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/fd05e9ef-bf19-4766-9121-a9ec01152301/1','- عُدلت هذه المادة وذلك  بموجب قرار مجلس الوزراء رقم (284) وتاريخ 1447/4/22هـ، لتكون بالنص الآتي: 

"يخضع منسوبو الصندوق -عدا المحافظ- لنظام العمل ونظام التأمينات الاجتماعية".')
